begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(18);
select has_column('public', 'profiles', 'applicant_status_details', 'Other situation has its own encrypted field');
select has_column('public', 'season_answers', 'applicant_status_details', 'the explanation belongs to the seasonal record too');
set local role authenticated;
set local request.jwt.claims = '{"sub":"5eed0000-0000-4000-8000-000000000011","role":"authenticated","aal":"aal1"}';
select lives_ok($$ select public.update_my_season_answers('{"applicant_status":"other","applicant_status_details":"Example explanation"}'::jsonb) $$, 'a player can save their explanation through the existing validated API');
select is((select applicant_status_details from public.get_own_profile()), 'Example explanation', 'the owner can recover their explanation');
select throws_ok($$ select public.update_my_season_answers(jsonb_build_object('applicant_status_details',repeat('x',2001))) $$, '22023', null::text, 'the server rejects text beyond the shared limit');
reset role;
select ok((select applicant_status_details is not null and encode(applicant_status_details,'escape') not like '%Example explanation%' from public.profiles where id='5eed0000-0000-4000-8000-000000000011'), 'the explanation is encrypted at rest');
select is((select public.decrypt_field(applicant_status_details) from public.season_answers where profile_id='5eed0000-0000-4000-8000-000000000011' order by updated_at desc limit 1), 'Example explanation', 'season snapshots keep the encrypted explanation');
set local role authenticated;
select lives_ok($$ select public.update_my_season_answers('{"childcare_need":"no"}'::jsonb) $$, 'a partial update preserves the situation explanation');
select is((select applicant_status_details from public.get_own_profile()), 'Example explanation', 'a sibling answer cannot wipe details');
select public.update_my_season_answers('{"applicant_status":"migrant"}'::jsonb);
select is((select applicant_status_details from public.get_own_profile()), null::text, 'choosing another status clears obsolete text');

reset role;
set local role anon;
select throws_ok($$ select * from public.get_own_profile() $$, '42501', null::text, 'anonymous clients cannot read situation explanations');
reset role;
set local role authenticated;
set local request.jwt.claims = '{"sub":"5eed0000-0000-4000-8000-000000000012","role":"authenticated","aal":"aal1"}';
select is((select count(*)::integer from public.get_participant_profile('5eed0000-0000-4000-8000-000000000011')),0,'another player cannot read the explanation');
reset role;
create temp table onboarding_account as select id from auth.users where email='onboarding@example.test';
grant select on onboarding_account to authenticated;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',(select id from onboarding_account),'role','authenticated','aal','aal1')::text,true);
select lives_ok($$ select public.complete_onboarding('{"first_name":"Nadia","last_name":"Khoury","date_of_birth":"1993-11-02","place_of_birth":"Homs","nationality":"Síria","preferred_language":"ca","document_type":"none","has_dependents":false,"num_dependents":0,"reference_entity":null,"clothing_size":"M","shoe_size":"38","media_consent":false,"terms_version":"2026-07-01","locale_shown":"ca","applicant_status":"other","applicant_status_details":"Wizard explanation"}'::jsonb) $$,'wizard completion saves the explanation atomically');
select is((select applicant_status_details from public.get_own_profile()),'Wizard explanation','wizard explanation is recoverable after completion');
reset role;
update public.profiles set applicant_status=public.encrypt_field('other'),applicant_status_details=public.encrypt_field('Example explanation') where id='5eed0000-0000-4000-8000-000000000011';
set local role authenticated;
set local request.jwt.claims = '{"sub":"5eed0000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","amr":[{"method":"totp","timestamp":4102444800}]}';
select is((select applicant_status_details from public.get_participant_profile('5eed0000-0000-4000-8000-000000000011')),'Example explanation','staff with sensitive access can read the explanation');
select lives_ok($$ select public.anonymize_participant('5eed0000-0000-4000-8000-000000000011') $$,'existing erasure includes the explanation');
reset role;
select ok((select applicant_status_details is null from public.profiles where id='5eed0000-0000-4000-8000-000000000011'),'erasure clears the profile explanation');
select is((select count(*)::integer from public.season_answers where profile_id='5eed0000-0000-4000-8000-000000000011' and applicant_status_details is not null),0,'erasure clears every seasonal copy');

select * from finish();
rollback;
